package commands

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/spf13/cobra"
	"github.com/spf13/cobra/doc"
)

// GenDocsPrefix is the name prefix of the Markdown files written by
// "nexoctl gendocs": one file per command, named after its path
// (nexoctl_admin_user_add.md).
const GenDocsPrefix = "nexoctl"

// newGenDocsCmd returns the hidden command that writes the Markdown
// reference of the whole command tree (docs/user/cli, make docs): one page
// per command generated by cobra/doc, with the pages of the commands that
// no longer exist removed, so that the directory always matches the tree.
func newGenDocsCmd(e *env) *cobra.Command {
	return &cobra.Command{
		Use:    "gendocs DIR",
		Short:  "Generate the Markdown reference of the commands into DIR",
		Hidden: true,
		Args:   exactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			n, err := GenMarkdownDocs(cmd.Root(), args[0])
			if err != nil {
				return err
			}
			return e.out.Info(genDocsRecord{Dir: args[0], Files: n},
				fmt.Sprintf("Wrote %d command pages to `%s`.", n, args[0]))
		},
	}
}

// genDocsRecord is the JSON record of gendocs.
type genDocsRecord struct {
	Dir   string `json:"dir"`
	Files int    `json:"files"`
}

// GenMarkdownDocs writes the Markdown reference of the command tree of root
// into dir (created when missing) with cobra/doc and returns the number of
// pages written: one page per available command (the hidden commands and
// the help command are skipped), named after the command path. The pages
// of a previous run (GenDocsPrefix*.md) are removed first, and the pages
// carry no date: two runs over the same tree produce the same files.
func GenMarkdownDocs(root *cobra.Command, dir string) (int, error) {
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return 0, fmt.Errorf("gendocs: %w", err)
	}
	stale, err := filepath.Glob(filepath.Join(dir, GenDocsPrefix+"*.md"))
	if err != nil {
		return 0, fmt.Errorf("gendocs: %w", err)
	}
	for _, f := range stale {
		if err := os.Remove(f); err != nil {
			return 0, fmt.Errorf("gendocs: %w", err)
		}
	}
	return genMarkdownTree(root, dir)
}

// genMarkdownTree writes the page of c and of its available subcommands,
// as doc.GenMarkdownTree does, and returns the number of pages.
func genMarkdownTree(c *cobra.Command, dir string) (int, error) {
	n := 0
	for _, sub := range c.Commands() {
		if !sub.IsAvailableCommand() || sub.IsAdditionalHelpTopicCommand() {
			continue
		}
		m, err := genMarkdownTree(sub, dir)
		if err != nil {
			return 0, err
		}
		n += m
	}
	// No "Auto generated by spf13/cobra on <date>" footer.
	c.DisableAutoGenTag = true
	var buf bytes.Buffer
	if err := doc.GenMarkdownCustom(c, &buf, func(link string) string { return link }); err != nil {
		return 0, fmt.Errorf("gendocs: %s: %w", c.CommandPath(), err)
	}
	name := filepath.Join(dir, strings.ReplaceAll(c.CommandPath(), " ", "_")+".md")
	page := polishPage(withAliases(buf.String(), c))
	if err := os.WriteFile(name, []byte(page), 0o644); err != nil { // #nosec G306 -- public documentation pages, committed to the repository
		return 0, fmt.Errorf("gendocs: %w", err)
	}
	return n + 1, nil
}

// withAliases adds to the page of c the section that lists its aliases
// (nexoctl alias ls), which cobra/doc leaves out, before the examples or
// the options.
func withAliases(page string, c *cobra.Command) string {
	if len(c.Aliases) == 0 {
		return page
	}
	parent := ""
	if c.HasParent() {
		parent = c.Parent().CommandPath() + " "
	}
	var b strings.Builder
	b.WriteString("### Aliases\n\n```\n")
	for _, a := range c.Aliases {
		b.WriteString(parent + a + "\n")
	}
	b.WriteString("```\n\n")
	for _, section := range []string{"### Examples\n", "### Options\n"} {
		if i := strings.Index(page, section); i >= 0 {
			return page[:i] + b.String() + page[i:]
		}
	}
	return page + "\n" + b.String()
}

// polishPage makes a generated page render as written in any Markdown
// engine (GitHub, MkDocs): the blanks that the flag tables of pflag leave
// at the end of some lines (hard line breaks) are removed, and the "*" and
// "_" of the prose (globs such as "*.example.com", names such as
// NEXO_KMS_SECRET_KEY) are escaped so that they are not read as emphasis.
// Code blocks (fenced or indented) and the links of the "SEE ALSO" list are
// kept as they are. The headings are promoted by one level: cobra/doc opens
// the page with "## nexoctl cp", and a page without a level-1 heading has
// no title in MkDocs (it falls back to the file name, "Nexoctl cp") nor a
// document outline that starts at its top.
func polishPage(page string) string {
	lines := strings.Split(page, "\n")
	fenced := false
	for i, l := range lines {
		l = strings.TrimRight(l, " \t")
		switch {
		case strings.HasPrefix(l, "```"):
			fenced = !fenced
		case fenced, strings.HasPrefix(l, "\t"), strings.HasPrefix(l, "    "):
		case strings.HasPrefix(l, "##"):
			l = l[1:]
		case strings.HasPrefix(l, "#"):
		case strings.HasPrefix(l, "* ["):
			// "* [nexoctl cp](nexoctl_cp.md)\t - Short": only the
			// description after the link is prose.
			if end := strings.Index(l, ")"); end > 0 {
				l = l[:end+1] + escapeEmphasis(l[end+1:])
			}
		default:
			l = escapeEmphasis(l)
		}
		lines[i] = l
	}
	return strings.Join(lines, "\n")
}

// escapeEmphasis escapes the Markdown emphasis characters of a line of
// prose, except in its inline code spans.
func escapeEmphasis(line string) string {
	var b strings.Builder
	code := false
	for _, r := range line {
		switch {
		case r == '`':
			code = !code
		case !code && (r == '*' || r == '_'):
			b.WriteByte('\\')
		}
		b.WriteRune(r)
	}
	return b.String()
}
